from taf.config.testline import Prisma, Airphone, TM500, Simulator, CUS


class UeAttrs(object):

    def __init__(self, ues):
        self.ues = (ues if ues is not None else [])

    def has_airphone(self):
        return any(isinstance(ue, Airphone) for ue in self.ues)

    def has_cus(self):
        return any(isinstance(ue, CUS) for ue in self.ues)

    def has_simulator(self):
        return any(isinstance(ue, (Simulator, Airphone, CUS)) for ue in self.ues)

    def has_prisma(self):
        return any(isinstance(ue, Prisma) for ue in self.ues)

    def has_tm500(self):
        return any(isinstance(ue, TM500) for ue in self.ues)

    def get_airphone_ues(self):
        if self.ues is None:
            raise AttributeError('No UE in testline object.')
        return [ue for ue in self.ues if isinstance(ue, Airphone)]

    def get_cus_ues(self):
        if self.ues is None:
            raise AttributeError('No UE in testline object.')
        return [ue for ue in self.ues if isinstance(ue, CUS)]

    def get_simulator_ues(self):
        if self.ues is None:
            raise AttributeError('No UE in testline object.')
        return [ue for ue in self.ues if isinstance(ue, (Airphone, CUS, Simulator))]

    def get_prisma_ues(self):
        if self.ues is None:
            raise AttributeError('No UE in testline object.')
        return [ue for ue in self.ues if isinstance(ue, Prisma)]

    def get_tm500_ues(self):
        if self.ues is None:
            raise AttributeError('No UE in testline object.')
        return [ue for ue in self.ues if isinstance(ue, TM500)]
